package com.codegym.product.controller;
import com.codegym.product.dao.ProductDAO; import com.codegym.product.model.Product; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException; import java.math.BigDecimal; import java.sql.SQLException;
@WebServlet("/products") public class ProductServlet extends HttpServlet { private final ProductDAO dao=new ProductDAO(); private void view(HttpServletRequest r,HttpServletResponse s,String page)throws ServletException,IOException{r.getRequestDispatcher("/WEB-INF/views/"+page).forward(r,s);} protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{String a=r.getParameter("action");if("new".equals(a)){r.setAttribute("product",new Product());view(r,s,"form.jsp");}else if("edit".equals(a)){Product p=dao.findById(Integer.parseInt(r.getParameter("id")));if(p==null){s.sendError(404);return;}r.setAttribute("product",p);view(r,s,"form.jsp");}else if("delete".equals(a)){dao.delete(Integer.parseInt(r.getParameter("id")));s.sendRedirect(r.getContextPath()+"/products");}else{r.setAttribute("products",dao.findAll());view(r,s,"list.jsp");}}catch(SQLException|NumberFormatException e){throw new ServletException(e);}} protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{String id=r.getParameter("id");Product p=new Product(id==null||id.isBlank()?0:Integer.parseInt(id),r.getParameter("name"),new BigDecimal(r.getParameter("price")),Integer.parseInt(r.getParameter("quantity")));dao.save(p);s.sendRedirect(r.getContextPath()+"/products");}catch(SQLException|NumberFormatException e){throw new ServletException(e);}} }
